import { init } from "./init.js";
import getPort, { makeRange } from "get-port";
import type { DevServerConfig } from "./config.js";
import { logListening } from "./logger.js";

export async function boot(config: DevServerConfig): Promise<any> {
  const resolvedPort = config.forcePort
    ? config.port
    : await getPort({
        host: config.host ?? "127.0.0.0",
        port: [config.port, ...makeRange(8081, 9000)],
      });
  const server = await init(config);
  await server.listen({ port: resolvedPort, host: config.host });
  if (!config.silent) logListening(config.host, resolvedPort);
  if (config.onListen) config.onListen(server);
  return server;
}
